'use client';

import { FilterChip } from './components/ui/filter-chip';
import { useState } from 'react';
export default function Example() {
  const [editing, setEditing] = useState(false);
  const [pending, setPending] = useState(false);
  const [selectedValues, setSelectedValues] = useState<string[]>([]);
  const options = [{ value: 'design', label: '디자인' }];
  return <><FilterChip label="분야" options={options} selectedValues={selectedValues} onClick={() => { setPending(selectedValues.includes('design')); setEditing(true); }} />{editing && <fieldset><legend>분야 필터</legend><label><input type="checkbox" checked={pending} onChange={event => setPending(event.currentTarget.checked)} />디자인</label><button type="button" onClick={() => { setSelectedValues(pending ? ['design'] : []); setEditing(false); }}>적용</button></fieldset>}</>;
}
